def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """Exponential warmup with cosine hold decay schedule."""
    if it > lr_decay_iters:
        return min_lr
    # Exponential warmup
    if it < warmup_iters:
        # Exponential growth: lr = learning_rate * (1 - exp(-5 * t)) where t = it / warmup_iters
        t = it / warmup_iters
        return learning_rate * (1.0 - math.exp(-5.0 * t))
    # Hold fraction: keep learning_rate for 30% of training after warmup
    hold_frac = 0.3
    hold_end = warmup_iters + int(hold_frac * (lr_decay_iters - warmup_iters))
    if it < hold_end:
        return learning_rate
    # Cosine decay from hold_end to lr_decay_iters
    decay_ratio = (it - hold_end) / (lr_decay_iters - hold_end)
    assert 0 <= decay_ratio <= 1
    coeff = 0.5 * (1.0 + math.cos(math.pi * decay_ratio))
    return min_lr + coeff * (learning_rate - min_lr)

