def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """Cosine annealing with warm restart at 70% of training."""
    total_iters = lr_decay_iters
    restart_iter = int(0.7 * total_iters)
    # Linear warmup
    if it < warmup_iters:
        return learning_rate * (it + 1) / (warmup_iters + 1)
    # First phase: cosine decay from warmup_iters to restart_iter
    if it < restart_iter:
        decay_ratio = (it - warmup_iters) / (restart_iter - warmup_iters)
        coeff = 0.5 * (1.0 + math.cos(math.pi * decay_ratio))
        return min_lr + coeff * (learning_rate - min_lr)
    # Second phase: restart with scaled max LR (0.8 * learning_rate)
    # Cosine decay from restart_iter to total_iters
    decay_ratio2 = (it - restart_iter) / (total_iters - restart_iter)
    coeff2 = 0.5 * (1.0 + math.cos(math.pi * decay_ratio2))
    max_lr2 = learning_rate * 0.8
    return min_lr + coeff2 * (max_lr2 - min_lr)

def get_lr(it, warmup_iters, lr_decay_iters, learning_rate, min_lr):
    """Exponential warmup with inverse sqrt decay."""
    if it > lr_decay_iters:
        return min_lr
    # Exponential warmup with slower growth (k=3)
    if it < warmup_iters:
        t = it / warmup_iters
        return learning_rate * (1.0 - math.exp(-3.0 * t))
    # Inverse sqrt decay
    t = (it - warmup_iters) / (lr_decay_iters - warmup_iters)
    # Compute c such that lr = learning_rate / sqrt(1 + c * t) reaches min_lr at t=1
    c = (learning_rate / min_lr) ** 2 - 1.0
    return learning_rate / math.sqrt(1.0 + c * t)

